(() => {
  const PW = 12.725, PD = 9.375, CX = PW/2, CZ = PD/2
  const RAD = 0.5 * Math.hypot(PW, PD, 2.7) * 1.1
  const fit = (r) => { const cam = window.__three.camera
    const half = Math.tan(((cam.fov||45) * Math.PI/180)/2)
    const a = Math.min(half, half * (cam.aspect||1))
    return r / Math.sin(Math.atan(a)) }
  window.__op = (azDeg, elDeg, scale) => {
    const t = window.__three, cam = t.camera, c = t.controls
    const d = fit(RAD) * (scale || 1)
    const az = azDeg*Math.PI/180, el = elDeg*Math.PI/180
    cam.position.set(CX + d*Math.cos(el)*Math.sin(az), 1.0 + d*Math.sin(el), CZ + d*Math.cos(el)*Math.cos(az))
    c.target.set(CX, 1.0, CZ); c.update()
  }
  window.__otop = () => { const t = window.__three, cam = t.camera, c = t.controls
    const d = fit(RAD)
    cam.position.set(CX, d, CZ + 0.01); c.target.set(CX, 0, CZ); c.update() }
  window.__od = (tx, tz, dist, azDeg, elDeg) => {
    const t = window.__three, cam = t.camera, c = t.controls
    const az = azDeg*Math.PI/180, el = elDeg*Math.PI/180
    cam.position.set(tx + dist*Math.cos(el)*Math.sin(az), 1.2 + dist*Math.sin(el), tz + dist*Math.cos(el)*Math.cos(az))
    c.target.set(tx, 1.2, tz); c.update() }
  window.__obootsave = () => { const t = window.__three
    window.__boot = { p: t.camera.position.toArray(), g: t.controls.target.toArray() } }
  window.__oboot = () => { const t = window.__three, b = window.__boot
    t.camera.position.set(b.p[0], b.p[1], b.p[2]); t.controls.target.set(b.g[0], b.g[1], b.g[2]); t.controls.update() }
})()
